/**
 * MCP server: lets Claude, ChatGPT or any MCP client read and edit the user's whole Resume
 * document. Clients sign in through Supabase Auth's OAuth 2.1 server; every tool runs as that
 * user (RLS applies). The tools live in src/mcp and are bundled into ./generated by
 * `npm run mcp:build` (mcp:serve and mcp:deploy run it first).
 *
 * Two public URLs reach it:
 * - the app's domain, `${APP_URL}/mcp`: Vercel forwards it here under the `_site` sub-path
 *   (vercel.json), so it is advertised as the resource and Supabase Auth as the issuer;
 * - the function's own URL, `https://<ref>.supabase.co/functions/v1/mcp`, as before, for
 *   connectors added with it (both identifiers derived from the request).
 */
import 'jsr:@supabase/functions-js/edge-runtime.d.ts'

import { createMcpHandler, McpServer } from '@modelcontextprotocol/server'
import { pipeline } from '@supabase/middleware'
import { fromSupabaseUrl, withOAuthProtectedResource, withSupabase } from '@supabase/server'
import { APP_URL, createSupabaseStore, INSTRUCTIONS, registerTools, SERVER_INFO } from './generated/mcp.js'

const SITE_SEGMENT = '_site'

async function handle(req: Request, { supabase, jwtClaims }: { supabase: Parameters<typeof createSupabaseStore>[0]; jwtClaims?: { sub?: string } }) {
  const userId = jwtClaims?.sub
  if (!userId) return new Response('Missing user', { status: 401 })
  // Edge Functions are stateless: a fresh server (and store) per request.
  const handler = createMcpHandler(() => {
    const server = new McpServer(SERVER_INFO, { instructions: INSTRUCTIONS })
    registerTools(server, { store: createSupabaseStore(supabase, userId) })
    return server
  })
  return handler.fetch(req)
}

const direct = pipeline([withOAuthProtectedResource(), withSupabase({ auth: 'user' })], handle)

// Through the app's domain the request's host says nothing reliable about this project, so both
// identifiers are fixed: the domain URL the client called, and the project's Auth as issuer.
const viaSite = pipeline(
  [
    withOAuthProtectedResource({
      resourceServer: `${APP_URL}/mcp`,
      authorizationServer: fromSupabaseUrl(Deno.env.get('SUPABASE_PUBLIC_URL') ?? Deno.env.get('SUPABASE_URL') ?? ''),
    }),
    withSupabase({ auth: 'user' }),
  ],
  handle,
)

Deno.serve((req) => (new URL(req.url).pathname.split('/').includes(SITE_SEGMENT) ? viaSite(req) : direct(req)))
